package ormgen

import (
	"os"
	"path/filepath"
	"testing"
)

// prune removes the generated files a generation did not write (the package
// of an entity that left the schema) and nothing a person wrote.
func TestPrune(t *testing.T) {
	dir := t.TempDir()
	write := func(rel, src string) {
		t.Helper()
		path := filepath.Join(dir, rel)
		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(src), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	write("user/user.go", header+"package user\n")
	write("gone/gone.go", header+"package gone\n")                                            // its entity was removed
	write("model/model.go", header+"package model\n")                                         // a package this version no longer generates
	write("mixed/old.go", header+"package mixed\n")                                           // generated, next to a hand-written file
	write("mixed/extra.go", "package mixed\n")                                                // hand-written
	write("notes/readme.md", "kept")                                                          // not Go
	write("legacy/client.go", "// Code generated by velox. DO NOT EDIT.\n\npackage legacy\n") // another generator's

	if err := prune(dir, map[string][]byte{filepath.Join("user", "user.go"): nil}); err != nil {
		t.Fatal(err)
	}
	for rel, want := range map[string]bool{
		"user/user.go": true, "gone/gone.go": false, "gone": false, "model": false,
		"mixed/old.go": false, "mixed/extra.go": true, "notes/readme.md": true, "legacy/client.go": true,
	} {
		_, err := os.Stat(filepath.Join(dir, rel))
		if got := err == nil; got != want {
			t.Errorf("%s: exists = %t, want %t", rel, got, want)
		}
	}
}
